def search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i
    return -1

def find_max(arr):
    max_val = arr[0]
    for i in range(1, len(arr)):
        if arr[i] > max_val:
            max_val = arr[i]
    return max_val

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):          # outer: runs n times
        for j in range(n - 1): # inner: runs n-1 times
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]

# Version A — in-place
def reverse_inplace(arr):
    left, right = 0, len(arr) - 1
    while left < right:
        arr[left], arr[right] = arr[right], arr[left]
        left += 1
        right -= 1

# Version B — out-of-place
def reverse_copy(arr):
    return arr[::-1]

